const marcaDeAguaDelEspejo = `-- name: MarcaDeAguaDelEspejo :one
SELECT max(o.pedido_updated_at)::timestamptz AS marca
FROM orders o
WHERE o.source = 'pedido'
  AND ($1::text IS NULL
       OR o.sucursal_codigo = $1::text)
`

// La marca de agua del espejo: `since` de la próxima bajada.
//
// Se DERIVA de los datos y no de un contador aparte a propósito: un contador se adelanta
// si una tanda falla a medias, y entonces el espejo se salta esos pedidos para siempre
// sin dar un solo error.
func (q *Queries) MarcaDeAguaDelEspejo(ctx context.Context, sucursalCodigo *string) (pgtype.Timestamptz, error) {
	row := q.db.QueryRow(ctx, marcaDeAguaDelEspejo, sucursalCodigo)
	var marca pgtype.Timestamptz
	err := row.Scan(&marca)
	return marca, err
}

